import{_ as t,o as a,a as i,a3 as o}from"./chunks/framework.CkbYhqXo.js";const m=JSON.parse('{"title":"Managing mods","description":"Install, update and manage mods in Stuzhik. Search the Modrinth and CurseForge catalog, automatic dependency install, conflict detection.","frontmatter":{"description":"Install, update and manage mods in Stuzhik. Search the Modrinth and CurseForge catalog, automatic dependency install, conflict detection.","head":[["meta",{"name":"keywords","content":"minecraft mods, stuzhik, how to install minecraft mods, modrinth, curseforge, forge mods, fabric mods, minecraft mod conflicts, minecraft mod dependencies"}]]},"headers":[],"relativePath":"en/guide/mods.md","filePath":"en/guide/mods.md"}'),l={name:"en/guide/mods.md"};function n(s,e,d,r,h,c){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="managing-mods" tabindex="-1">Managing mods <a class="header-anchor" href="#managing-mods" aria-label="Permalink to &quot;Managing mods&quot;">​</a></h1><h2 id="installing-mods" tabindex="-1">Installing mods <a class="header-anchor" href="#installing-mods" aria-label="Permalink to &quot;Installing mods&quot;">​</a></h2><h3 id="from-the-catalog" tabindex="-1">From the catalog <a class="header-anchor" href="#from-the-catalog" aria-label="Permalink to &quot;From the catalog&quot;">​</a></h3><ol><li>Open the instance</li><li>The &quot;Mods&quot; tab → &quot;Catalog&quot;</li><li>Find the mod with search</li><li>The &quot;Install&quot; button</li></ol><p>Stuzhik automatically:</p><ul><li>Picks the version for your Minecraft version and loader — one that works next to the mods already installed (the latest release, if it fits)</li><li>Warns you about conflicts</li><li>Installs dependencies</li></ul><p>While a mod installs, its card shows what&#39;s going on: &quot;Picking a version…&quot;, &quot;Downloading · N%&quot; with a bar, &quot;Dependencies…&quot;. The &quot;Cancel install&quot; cross stops it. If the mod&#39;s file has already downloaded, the mod stays in the build, and the dependencies that didn&#39;t make it in are listed on the &quot;Dependencies&quot; tab. Everything being installed into this build is also visible on the &quot;Mods&quot; tab — in the &quot;Installing&quot; block above the list.</p><h3 id="from-a-file" tabindex="-1">From a file <a class="header-anchor" href="#from-a-file" aria-label="Permalink to &quot;From a file&quot;">​</a></h3><p>Drag a <code>.jar</code> file into the window, or:</p><ol><li>The &quot;Add local mod&quot; button</li><li>Choose the <code>.jar</code> file</li><li>Done</li></ol><h3 id="dependencies" tabindex="-1">Dependencies <a class="header-anchor" href="#dependencies" aria-label="Permalink to &quot;Dependencies&quot;">​</a></h3><p>If a mod needs other mods:</p><ol><li>Stuzhik shows the list of dependencies</li><li>The &quot;Install All&quot; button</li><li>All dependencies are installed automatically</li></ol><h2 id="mod-details" tabindex="-1">Mod details <a class="header-anchor" href="#mod-details" aria-label="Permalink to &quot;Mod details&quot;">​</a></h2><p>Clicking a mod in the list opens its card with the description, the full version history and the dependency graph:</p><ul><li><strong>Changing the version</strong> — you pick a version from the list right in the card, no need to remove and reinstall</li><li><strong>Hide incompatible</strong> — a checkbox filters out the versions that definitely won&#39;t fit the current MC/loader</li><li><strong>Dependency graph</strong> — you can see at a glance what depends on what and what conflicts with what</li><li><strong>Wishlist</strong> — the heart icon adds a mod to your favorites right from the catalog, even if you don&#39;t plan to install it yet</li></ul><h2 id="managing-mods-1" tabindex="-1">Managing mods <a class="header-anchor" href="#managing-mods-1" aria-label="Permalink to &quot;Managing mods&quot;">​</a></h2><h3 id="enabling-disabling" tabindex="-1">Enabling/disabling <a class="header-anchor" href="#enabling-disabling" aria-label="Permalink to &quot;Enabling/disabling&quot;">​</a></h3><ol><li>Mod list → click the toggle</li><li>The mod is renamed to <code>.jar.disabled</code></li><li>It won&#39;t load on the next launch</li></ol><h3 id="updating" tabindex="-1">Updating <a class="header-anchor" href="#updating" aria-label="Permalink to &quot;Updating&quot;">​</a></h3><p><strong>Manually:</strong></p><ol><li>Click the mod → &quot;Update&quot;</li><li>Stuzhik finds a newer version that fits the build</li><li>Replaces the file. If the download fails, the old file stays in place</li></ol><p>A version that shouldn&#39;t be updated can be pinned: the pin icon in the mod&#39;s row, or &quot;Pin the version&quot; in the right-click menu. Updates, auto-update and modpack updates leave a pinned version alone.</p><p><strong>Automatically:</strong></p><ol><li>Mod list → the auto-update icon in the mod&#39;s row (tooltip &quot;Auto-update disabled&quot; / &quot;Auto-update enabled&quot;)</li><li>A found update installs by itself when you check mod updates with the &quot;Updates&quot; button</li></ol><h3 id="removing" tabindex="-1">Removing <a class="header-anchor" href="#removing" aria-label="Permalink to &quot;Removing&quot;">​</a></h3><ol><li>Click the mod → &quot;Delete&quot;</li><li>Or select several → &quot;Delete selected&quot;</li></ol><h2 id="finding-mods" tabindex="-1">Finding mods <a class="header-anchor" href="#finding-mods" aria-label="Permalink to &quot;Finding mods&quot;">​</a></h2><h3 id="filters" tabindex="-1">Filters <a class="header-anchor" href="#filters" aria-label="Permalink to &quot;Filters&quot;">​</a></h3><ul><li><strong>Category:</strong> Technology, Magic, Decoration, etc.</li><li><strong>Loader and MC version:</strong> taken from the instance — only compatible mods are shown. The &quot;Show incompatible&quot; checkbox lifts this filter</li><li><strong>Source:</strong> Modrinth/CurseForge</li></ul><h3 id="sorting" tabindex="-1">Sorting <a class="header-anchor" href="#sorting" aria-label="Permalink to &quot;Sorting&quot;">​</a></h3><ul><li>Relevance</li><li>Popular (by downloads)</li><li>By follows</li><li>Newest</li><li>Updated</li></ul><h2 id="mod-conflicts" tabindex="-1">Mod conflicts <a class="header-anchor" href="#mod-conflicts" aria-label="Permalink to &quot;Mod conflicts {#mod-conflicts}&quot;">​</a></h2><h3 id="automatic-check" tabindex="-1">Automatic check <a class="header-anchor" href="#automatic-check" aria-label="Permalink to &quot;Automatic check&quot;">​</a></h3><p>During install, Stuzhik checks for:</p><table tabindex="0"><thead><tr><th>Conflict type</th><th>Example</th></tr></thead><tbody><tr><td>Incompatibility</td><td>OptiFine + Sodium</td></tr><tr><td>Duplicates</td><td>Sodium + Rubidium</td></tr><tr><td>Loader mismatch</td><td>Forge mod on Fabric</td></tr><tr><td>MC version</td><td>Mod for 1.19 on 1.20</td></tr></tbody></table><h3 id="resolving-conflicts" tabindex="-1">Resolving conflicts <a class="header-anchor" href="#resolving-conflicts" aria-label="Permalink to &quot;Resolving conflicts&quot;">​</a></h3><p>If a conflict is found:</p><ol><li><strong>Critical</strong> - install is blocked</li><li><strong>Warning</strong> - you can install it, but the game will crash</li><li><strong>Info</strong> - it will work, but there may be bugs</li></ol><p>Stuzhik will offer to:</p><ul><li>Remove the conflicting mod</li><li>Install an alternative</li><li>Ignore it (at your own risk)</li></ul><h3 id="the-dependencies-tab" tabindex="-1">The &quot;Dependencies&quot; tab <a class="header-anchor" href="#the-dependencies-tab" aria-label="Permalink to &quot;The &quot;Dependencies&quot; tab&quot;">​</a></h3><p>A separate tab in the instance details shows all problems at once: missing dependencies, mismatched versions, incompatible pairs. The &quot;Install all missing&quot; button resolves the missing dependencies in one click — no need to find and install each one by hand.</p><h2 id="recommendations" tabindex="-1">Recommendations <a class="header-anchor" href="#recommendations" aria-label="Permalink to &quot;Recommendations {#recommendations}&quot;">​</a></h2><h3 id="based-on-what-s-installed" tabindex="-1">Based on what&#39;s installed <a class="header-anchor" href="#based-on-what-s-installed" aria-label="Permalink to &quot;Based on what&#39;s installed&quot;">​</a></h3><p>Stuzhik looks at:</p><ul><li>The categories of installed mods</li><li>Popular combinations</li><li>Addons for mods</li></ul><p>And suggests mods that:</p><ul><li>Complement the installed ones</li><li>Are popular alongside them</li><li>Are dependencies of other mods</li></ul><h3 id="trending" tabindex="-1">Trending <a class="header-anchor" href="#trending" aria-label="Permalink to &quot;Trending&quot;">​</a></h3><p>Shows popular mods for:</p><ul><li>Your Minecraft version</li><li>Your loader</li><li>Categories you already have installed</li></ul><h2 id="performance" tabindex="-1">Performance <a class="header-anchor" href="#performance" aria-label="Permalink to &quot;Performance {#performance}&quot;">​</a></h2><h3 id="optimization" tabindex="-1">Optimization <a class="header-anchor" href="#optimization" aria-label="Permalink to &quot;Optimization&quot;">​</a></h3><p>Mods that improve FPS:</p><p><strong>Forge:</strong></p><ul><li>Optifine (alternative: Embeddium + Oculus)</li><li>EntityCulling</li><li>FpsReducer</li></ul><p><strong>Fabric:</strong></p><ul><li>Sodium</li><li>Lithium</li><li>Phosphor</li><li>Entity Culling</li></ul><h3 id="monitoring" tabindex="-1">Monitoring <a class="header-anchor" href="#monitoring" aria-label="Permalink to &quot;Monitoring&quot;">​</a></h3><p>Stuzhik shows:</p><ul><li>How much disk space mods take</li><li>Their impact on loading time</li><li>Suspicious mods when crashes happen</li></ul><h2 id="where-mods-are-stored" tabindex="-1">Where mods are stored <a class="header-anchor" href="#where-mods-are-stored" aria-label="Permalink to &quot;Where mods are stored&quot;">​</a></h2><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-dark vp-code" tabindex="0"><code><span class="line"><span>Windows: %APPDATA%\\ru.sibxodev.stuzhik\\instances\\&lt;id&gt;\\mods\\</span></span></code></pre></div><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><h3 id="a-mod-doesn-t-show-up-in-the-game" tabindex="-1">A mod doesn&#39;t show up in the game <a class="header-anchor" href="#a-mod-doesn-t-show-up-in-the-game" aria-label="Permalink to &quot;A mod doesn&#39;t show up in the game&quot;">​</a></h3><p><strong>Check:</strong></p><ol><li>Is it the right loader? (Forge mod on Forge)</li><li>Is it the right MC version?</li><li>Is the mod enabled? (not <code>.disabled</code>)</li><li>Are its dependencies there? (Fabric API for Fabric)</li></ol><h3 id="crash-after-installing-a-mod" tabindex="-1">Crash after installing a mod <a class="header-anchor" href="#crash-after-installing-a-mod" aria-label="Permalink to &quot;Crash after installing a mod&quot;">​</a></h3><ol><li>The Log Analyzer finds the mod to blame automatically</li><li>Remove the mod through Stuzhik</li><li>Or roll back its version: open the mod&#39;s card → the &quot;Versions&quot; tab → pick the earlier version</li></ol><h3 id="a-mod-doesn-t-update" tabindex="-1">A mod doesn&#39;t update <a class="header-anchor" href="#a-mod-doesn-t-update" aria-label="Permalink to &quot;A mod doesn&#39;t update&quot;">​</a></h3><ol><li>Check that auto-update is turned on</li><li>The new version may be for a newer MC only</li><li>Developer Console (<code>Ctrl+Shift+D</code>) → any errors?</li></ol>',72)])])}const g=t(l,[["render",n]]);export{m as __pageData,g as default};
